import{_ as t,o,c as n,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const s="/rakkii-cars-guide/screenshots/07-lane-3-corporate-government-bidding-blanket-pos/01-blanket-po-detail.png",u=JSON.parse('{"title":"7. Lane 3 — Corporate, government, bidding & blanket POs","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/07-lane-3-corporate-government-bidding-blanket-pos.md","filePath":"chapters/07-lane-3-corporate-government-bidding-blanket-pos.md","lastUpdated":1793268728000}'),a={name:"chapters/07-lane-3-corporate-government-bidding-blanket-pos.md"};function i(l,e,d,g,p,h){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_7-lane-3-—-corporate-government-bidding-blanket-pos" tabindex="-1">7. Lane 3 — Corporate, government, bidding &amp; blanket POs <a class="header-anchor" href="#_7-lane-3-—-corporate-government-bidding-blanket-pos" aria-label="Permalink to &quot;7. Lane 3 — Corporate, government, bidding &amp; blanket POs&quot;">​</a></h1><p><strong>For:</strong> Shop Owner · <strong>Hubs:</strong> Workshop, Finance · <strong>Nature:</strong> Corporate, Government or Bidding · <strong>Job type:</strong> usually Fleet</p><p>Fleet and institutional customers do not pay cash at the counter. They issue purchase orders (POs), bid awards and BAC resolutions, and they pay on credit terms after you bill. Rakkii Ops lets you hold work until the paper is in, and release the car on terms once the invoice is posted.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Company/Government customer (TIN, credit terms) → Blanket PO (if any) → Job with nature</span></span>\n<span class="line"><span>→ Paperwork gate (Approved PO / Notice of award / BAC resolution) → Repair → QC</span></span>\n<span class="line"><span>→ Post customer invoice → Release on credit terms → Collect in Who owes us</span></span></code></pre></div><h2 id="_7-1-set-up-the-company-customer-workshop-customers" tabindex="-1">7.1 Set up the company customer (<code>/workshop/customers</code>) <a class="header-anchor" href="#_7-1-set-up-the-company-customer-workshop-customers" aria-label="Permalink to &quot;7.1 Set up the company customer (`/workshop/customers`)&quot;">​</a></h2><ol><li><strong>Workshop › Customers › New customer</strong>.</li><li><strong>Identity</strong>: <strong>Name</strong> (company or agency), <strong>Mobile</strong> (required — use the fleet officer&#39;s number), <strong>Email</strong>, <strong>Category</strong> = <strong>Company</strong> or <strong>Government</strong>, <strong>Notes</strong>.</li><li><strong>Billing</strong>: <ul><li><strong>TIN</strong> (follows the format hint shown)</li><li><strong>Credit terms (days)</strong> — for example <strong>30</strong>. Blank uses the shop default; <strong>0</strong> means due on issue.</li><li><strong>Billing address</strong></li></ul></li><li><strong>Save customer</strong>. The customer page shows <strong>Credit terms: 30 days</strong>.</li></ol><p>Add the fleet&#39;s cars under <strong>Cars › Add car</strong> so each job picks the right vehicle.</p><h2 id="_7-2-blanket-pos-finance-blanket-pos" tabindex="-1">7.2 Blanket POs (<code>/finance/blanket-pos</code>) <a class="header-anchor" href="#_7-2-blanket-pos-finance-blanket-pos" aria-label="Permalink to &quot;7.2 Blanket POs (`/finance/blanket-pos`)&quot;">​</a></h2><p>A blanket PO is one purchase order that covers a group of vehicles as they arrive (for example &quot;PO-2026-118, 12 patrol cars, PHP 1,800,000&quot;).</p><h3 id="create-the-po" tabindex="-1">Create the PO <a class="header-anchor" href="#create-the-po" aria-label="Permalink to &quot;Create the PO&quot;">​</a></h3><ol><li><strong>Finance › Blanket POs › New blanket PO</strong>.</li><li><strong>Party kind</strong>: Government or Corporate. <strong>Party name</strong>. <strong>PO number</strong>. <strong>Authorized ₱</strong> (the total ceiling). <strong>Expected units</strong>.</li><li><strong>Save PO</strong>.</li></ol><h3 id="manage-the-po-finance-blanket-pos-id" tabindex="-1">Manage the PO (<code>/finance/blanket-pos/:id</code>) <a class="header-anchor" href="#manage-the-po-finance-blanket-pos-id" aria-label="Permalink to &quot;Manage the PO (`/finance/blanket-pos/:id`)&quot;">​</a></h3><ul><li><strong>Details</strong> — edit <strong>Authorized ₱</strong>, <strong>Expected units</strong>, <strong>Status</strong> (Open, Closed, Cancelled) and <strong>Notes</strong>. There is no separate validity-date field: record the PO validity period in <strong>Notes</strong> and set the status to <strong>Closed</strong> when it expires.</li><li><strong>PO soft copy</strong> — <strong>Upload</strong> the signed PO.</li><li><strong>Model caps</strong> — when the PO sets a peso cap per vehicle model, each cap shows used, left and expected units.</li><li><strong>Linked vehicles</strong> — plate, reference, status, car-in date, <strong>Consumed</strong>, balance and age; plus &quot;<em>n</em> units not yet in (of <em>m</em> expected)&quot;.</li><li><strong>Aging</strong> of balances on linked jobs.</li></ul><h3 id="link-jobs-to-draw-down-the-balance" tabindex="-1">Link jobs to draw down the balance <a class="header-anchor" href="#link-jobs-to-draw-down-the-balance" aria-label="Permalink to &quot;Link jobs to draw down the balance&quot;">​</a></h3><ol><li>On the PO page use <strong>Link a job</strong>, choose the job, press <strong>Link job</strong>.</li><li>The job&#39;s billed amount is consumed from the PO. The page shows &quot;Remaining ₱… of ₱…&quot;.</li><li>A link that goes past the remaining amount or a model cap is refused. The owner can enter an <strong>Owner override reason</strong> and press <strong>Link with Owner override</strong> (written to the money log).</li><li><strong>Unlink</strong> if a job was linked by mistake. A Closed or Cancelled PO accepts no new links.</li></ol><p>The job header shows a chip &quot;Blanket PO <em>number</em> · remaining ₱…&quot;.</p><p>On the list page, the <strong>Open</strong> and <strong>History</strong> views, filters by <strong>Status</strong> and <strong>Party kind</strong>, <strong>Export CSV</strong> and <strong>Print</strong> help you report to the customer.</p><p><img src="'+s+'" alt="Blanket PO detail with remaining amount, linked vehicles and model caps"></p><h2 id="_7-3-create-the-job" tabindex="-1">7.3 Create the job <a class="header-anchor" href="#_7-3-create-the-job" aria-label="Permalink to &quot;7.3 Create the job&quot;">​</a></h2><ol><li><strong>New job</strong> with <strong>Nature</strong> = Corporate, Government or Bidding and <strong>Job type</strong> = Fleet (or Retail).</li><li>Choose the company customer and the car.</li><li>If the PO is per job, open <strong>Work › Technicians and dates</strong> and enter <strong>Approved PO amount</strong> and <strong>PO approved on</strong>, then <strong>Save dates</strong>. The Overview line reads &quot;Nature · Approved PO ₱…&quot;.</li></ol><h2 id="_7-4-paperwork-gates-before-work-starts" tabindex="-1">7.4 Paperwork gates before work starts <a class="header-anchor" href="#_7-4-paperwork-gates-before-work-starts" aria-label="Permalink to &quot;7.4 Paperwork gates before work starts&quot;">​</a></h2><p>The owner turns each gate on in <strong>Admin › Shop settings › Workshop rules › Paperwork by customer type</strong> (all off by default):</p><table tabindex="0"><thead><tr><th>Nature</th><th>Gate</th><th>What satisfies it</th><th>Message if missing</th></tr></thead><tbody><tr><td>Corporate</td><td><strong>Corporate needs an approved PO</strong></td><td>Approved PO amount / date on the job</td><td>&quot;An approved PO is required before work starts.&quot;</td></tr><tr><td>Government</td><td><strong>Government needs a PO or blanket PO</strong></td><td>Approved PO, or a linked blanket PO</td><td>&quot;An approved PO or a blanket PO is required before work starts.&quot;</td></tr><tr><td>Government</td><td><strong>Government needs a BAC resolution</strong></td><td>File of kind <strong>BAC resolution</strong></td><td>&quot;A BAC resolution is required before work starts.&quot;</td></tr><tr><td>Bidding</td><td><strong>Bidding needs an award</strong></td><td>File of kind <strong>Notice of award</strong></td><td>&quot;A notice of award is required before work starts.&quot;</td></tr></tbody></table><p><strong>Upload the documents:</strong> <strong>Files</strong> tab → choose <strong>Kind</strong> (Notice of award, BAC resolution, Certificate of final acceptance, PDF…) → upload. Government and Bidding jobs show a document checklist (○ missing, ✓ uploaded).</p><p><strong>Skip a gate for one job:</strong> owner (or admin) only — <strong>Skip this job&#39;s document gate</strong>, type a reason, <strong>Save skip reason</strong>. The job can then start without the LOA, approved PO, blanket PO, notice of award or BAC resolution.</p><h3 id="down-payment-for-these-natures" tabindex="-1">Down payment for these natures <a class="header-anchor" href="#down-payment-for-these-natures" aria-label="Permalink to &quot;Down payment for these natures&quot;">​</a></h3><p>Corporate, Government and Bidding each have their own down-payment percent (50% by default) and blocking rule (<strong>Does not block</strong> by default). See <a href="/rakkii-cars-guide/chapters/13-admin-shop-settings-and-staff-permissions">Chapter 13</a>.</p><h2 id="_7-5-repair-qc-and-invoice" tabindex="-1">7.5 Repair, QC and invoice <a class="header-anchor" href="#_7-5-repair-qc-and-invoice" aria-label="Permalink to &quot;7.5 Repair, QC and invoice&quot;">​</a></h2><p>Run the repair as in <a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs">Chapter 5</a>: assign, <strong>Start work</strong>, bay checklist, four QC photos, <strong>Ready for pickup</strong>.</p><p>Then <strong>Pay › Invoices › Bill customer ₱…</strong> to post the invoice in the company&#39;s name (TIN and billing address on the print). If the shop has a withholding percent for corporate or government payers, the Pay tab shows <strong>Expected withholding</strong> and <strong>Expected net</strong> — record the amount that actually arrives.</p><h2 id="_7-6-release-on-credit-terms" tabindex="-1">7.6 Release on credit terms <a class="header-anchor" href="#_7-6-release-on-credit-terms" aria-label="Permalink to &quot;7.6 Release on credit terms&quot;">​</a></h2><p>A job counts as a <strong>credit job</strong> when any of these is true:</p><ul><li>the customer has <strong>Credit terms (days)</strong> above 0, or</li><li>the job has an <strong>Approved PO amount</strong> or <strong>PO approved on</strong> date, or</li><li>the job is linked to a <strong>blanket PO</strong>.</li></ul><p>Once the customer invoice is <strong>posted</strong>, a credit job releases <strong>without upfront cash</strong>:</p><ol><li>Open <strong>Release</strong>. The tab says &quot;Releasing on credit terms or an approved PO.&quot;</li><li>Tick <strong>Keys logged</strong>, <strong>Documents in / out</strong> and <strong>Customer signed release</strong>.</li><li>Press <strong>Release car</strong>. No owner override is needed even though the balance is open.</li></ol><p>The open balance moves to <strong>Finance › Who owes us</strong> with the due date from the credit terms. Send the billing transmittal and follow up as in <a href="/rakkii-cars-guide/chapters/08-lane-4-billing-chain-receivables-storage-credit-notes">Chapter 8</a>.</p><div class="warning custom-block"><p class="custom-block-title">No invoice, no credit release</p><p>Without a posted customer invoice the normal hold applies: &quot;Customer still owes. Default is to hold the car.&quot;</p></div>',37)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
